const OPTION_DEFINITIONS = [
  { flag: '--key1', name: 'key1', metavar: 'KEY1' },
  { flag: '--key2', name: 'key2', metavar: 'KEY2' },
  { flag: '--data', name: 'data', metavar: 'DATA' },
];

const HELP_FLAGS = new Set(['-h', '--help']);
const OPTION_BY_FLAG = new Map(OPTION_DEFINITIONS.map((option) => [option.flag, option]));

export class CliExit extends Error {
  constructor(code, output, stream) {
    super(output);
    this.name = 'CliExit';
    this.code = code;
    this.output = output;
    this.stream = stream;
  }
}

export function basename(pathname) {
  const normalized = String(pathname ?? '').replace(/\\/g, '/');
  const pieces = normalized.split('/');
  return pieces[pieces.length - 1] || normalized;
}

export function formatUsage(progName) {
  return `usage: ${progName} [-h] --key1 KEY1 --key2 KEY2 --data DATA`;
}

export function formatHelp(progName) {
  return `${formatUsage(progName)}

options:
  -h, --help   show this help message and exit
  --key1 KEY1
  --key2 KEY2
  --data DATA
`;
}

function createErrorExit(progName, message) {
  return new CliExit(2, `${formatUsage(progName)}
${progName}: error: ${message}
`, 'stderr');
}

function isOptionLike(token) {
  return typeof token === 'string' && token.startsWith('-') && token !== '-';
}

function splitLongOption(token) {
  const equalsIndex = token.indexOf('=');
  if (equalsIndex === -1) {
    return { flag: token, hasInlineValue: false, inlineValue: '' };
  }

  return {
    flag: token.slice(0, equalsIndex),
    hasInlineValue: true,
    inlineValue: token.slice(equalsIndex + 1),
  };
}

export function parseCommandLine(argv, progName) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (HELP_FLAGS.has(token)) {
      throw new CliExit(0, formatHelp(progName), 'stdout');
    }

    const { flag, hasInlineValue, inlineValue } = splitLongOption(token);
    const option = OPTION_BY_FLAG.get(flag);

    if (option) {
      if (hasInlineValue) {
        values[option.name] = inlineValue;
        continue;
      }

      const nextToken = argv[index + 1];
      if (nextToken === undefined || isOptionLike(nextToken)) {
        throw createErrorExit(progName, `argument ${flag}: expected one argument`);
      }

      values[option.name] = nextToken;
      index += 1;
      continue;
    }

    if (isOptionLike(token)) {
      extras.push(token);

      if (!hasInlineValue && index + 1 < argv.length && !isOptionLike(argv[index + 1])) {
        extras.push(argv[index + 1]);
        index += 1;
      }

      continue;
    }

    extras.push(token);
  }

  const missing = OPTION_DEFINITIONS
    .filter((option) => values[option.name] === undefined)
    .map((option) => option.flag);

  if (missing.length > 0) {
    throw createErrorExit(progName, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    throw createErrorExit(progName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

