function chooseQuote(bytes) {
  let hasSingleQuote = false;
  let hasDoubleQuote = false;

  for (const value of bytes) {
    if (value === 0x27) {
      hasSingleQuote = true;
    } else if (value === 0x22) {
      hasDoubleQuote = true;
    }
  }

  return hasSingleQuote && !hasDoubleQuote ? '"' : "'";
}

function escapeByte(value, quoteCode) {
  if (value === 0x5c) {
    return '\\\\';
  }

  if (value === quoteCode) {
    return `\\${String.fromCharCode(quoteCode)}`;
  }

  if (value === 0x09) {
    return '\\t';
  }

  if (value === 0x0a) {
    return '\\n';
  }

  if (value === 0x0d) {
    return '\\r';
  }

  if (value >= 0x20 && value <= 0x7e) {
    return String.fromCharCode(value);
  }

  return `\\x${value.toString(16).padStart(2, '0')}`;
}

export function toPythonBytesRepr(bytes) {
  const data = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);
  const quote = chooseQuote(data);
  const quoteCode = quote.charCodeAt(0);

  let repr = `b${quote}`;
  for (const value of data) {
    repr += escapeByte(value, quoteCode);
  }
  repr += quote;

  return repr;
}

import {
  AesEcbCipher,
  CliExit,
  ValueError,
  basename,
  encodeUtf8,
  parseCommandLine,
  toPythonBytesRepr,
} from './lib/index.mjs';

function writeAndExit(stream, output, code) {
  stream.write(output);
  process.exit(code);
}

export function main(argv = process.argv.slice(2)) {
  const progName = basename(process.argv[1] ?? 'test15.mjs');

  let args;
  try {
    args = parseCommandLine(argv, progName);
  } catch (error) {
    if (error instanceof CliExit) {
      const stream = error.stream === 'stderr' ? process.stderr : process.stdout;
      writeAndExit(stream, error.output, error.code);
    }

    throw error;
  }

  try {
    const aes1 = new AesEcbCipher(encodeUtf8(args.key1));
    const aes2 = new AesEcbCipher(encodeUtf8(args.key2));
    const ciphertext = aes1.encrypt(encodeUtf8(args.data));
    const wrongPlaintext = aes2.decrypt(ciphertext);

    console.log(toPythonBytesRepr(ciphertext));
    console.log(toPythonBytesRepr(wrongPlaintext));
  } catch (error) {
    if (error instanceof ValueError) {
      writeAndExit(process.stderr, `${error.name}: ${error.message}\n`, 1);
    }

    throw error;
  }
}

main();

import { gfMultiply } from './finite_field.mjs';
import { inverseSBox, roundConstants, sBox } from './tables.mjs';

const BLOCK_SIZE = 16;
const VALID_KEY_SIZES = new Set([16, 24, 32]);

export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

function copyBytes(bytes) {
  return bytes instanceof Uint8Array ? Uint8Array.from(bytes) : Uint8Array.from(bytes);
}

function subWord(word) {
  for (let index = 0; index < word.length; index += 1) {
    word[index] = sBox[word[index]];
  }
}

function rotWord(word) {
  const first = word[0];
  word[0] = word[1];
  word[1] = word[2];
  word[2] = word[3];
  word[3] = first;
}

function expandKey(keyBytes) {
  const key = copyBytes(keyBytes);
  if (!VALID_KEY_SIZES.has(key.length)) {
    throw new ValueError('Invalid key size');
  }

  const wordsInKey = key.length / 4;
  const roundCount = wordsInKey + 6;
  const expandedKey = new Uint8Array(BLOCK_SIZE * (roundCount + 1));
  const temp = new Uint8Array(4);

  expandedKey.set(key);

  let bytesGenerated = key.length;
  let roundConstantIndex = 1;

  while (bytesGenerated < expandedKey.length) {
    temp[0] = expandedKey[bytesGenerated - 4];
    temp[1] = expandedKey[bytesGenerated - 3];
    temp[2] = expandedKey[bytesGenerated - 2];
    temp[3] = expandedKey[bytesGenerated - 1];

    if (bytesGenerated % key.length === 0) {
      rotWord(temp);
      subWord(temp);
      temp[0] ^= roundConstants[roundConstantIndex];
      roundConstantIndex += 1;
    } else if (wordsInKey > 6 && bytesGenerated % key.length === 16) {
      subWord(temp);
    }

    for (let index = 0; index < 4; index += 1) {
      expandedKey[bytesGenerated] = expandedKey[bytesGenerated - key.length] ^ temp[index];
      bytesGenerated += 1;
    }
  }

  return { expandedKey, roundCount };
}

function addRoundKey(state, expandedKey, round) {
  const offset = round * BLOCK_SIZE;
  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    state[index] ^= expandedKey[offset + index];
  }
}

function subBytes(state) {
  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    state[index] = sBox[state[index]];
  }
}

function inverseSubBytes(state) {
  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    state[index] = inverseSBox[state[index]];
  }
}

function shiftRows(state) {
  const copy = state.slice();

  state[1] = copy[5];
  state[5] = copy[9];
  state[9] = copy[13];
  state[13] = copy[1];

  state[2] = copy[10];
  state[6] = copy[14];
  state[10] = copy[2];
  state[14] = copy[6];

  state[3] = copy[15];
  state[7] = copy[3];
  state[11] = copy[7];
  state[15] = copy[11];
}

function inverseShiftRows(state) {
  const copy = state.slice();

  state[1] = copy[13];
  state[5] = copy[1];
  state[9] = copy[5];
  state[13] = copy[9];

  state[2] = copy[10];
  state[6] = copy[14];
  state[10] = copy[2];
  state[14] = copy[6];

  state[3] = copy[7];
  state[7] = copy[11];
  state[11] = copy[15];
  state[15] = copy[3];
}

function mixColumns(state) {
  for (let column = 0; column < BLOCK_SIZE; column += 4) {
    const s0 = state[column];
    const s1 = state[column + 1];
    const s2 = state[column + 2];
    const s3 = state[column + 3];

    state[column] = gfMultiply(s0, 0x02) ^ gfMultiply(s1, 0x03) ^ s2 ^ s3;
    state[column + 1] = s0 ^ gfMultiply(s1, 0x02) ^ gfMultiply(s2, 0x03) ^ s3;
    state[column + 2] = s0 ^ s1 ^ gfMultiply(s2, 0x02) ^ gfMultiply(s3, 0x03);
    state[column + 3] = gfMultiply(s0, 0x03) ^ s1 ^ s2 ^ gfMultiply(s3, 0x02);
  }
}

function inverseMixColumns(state) {
  for (let column = 0; column < BLOCK_SIZE; column += 4) {
    const s0 = state[column];
    const s1 = state[column + 1];
    const s2 = state[column + 2];
    const s3 = state[column + 3];

    state[column] =
      gfMultiply(s0, 0x0e) ^ gfMultiply(s1, 0x0b) ^ gfMultiply(s2, 0x0d) ^ gfMultiply(s3, 0x09);
    state[column + 1] =
      gfMultiply(s0, 0x09) ^ gfMultiply(s1, 0x0e) ^ gfMultiply(s2, 0x0b) ^ gfMultiply(s3, 0x0d);
    state[column + 2] =
      gfMultiply(s0, 0x0d) ^ gfMultiply(s1, 0x09) ^ gfMultiply(s2, 0x0e) ^ gfMultiply(s3, 0x0b);
    state[column + 3] =
      gfMultiply(s0, 0x0b) ^ gfMultiply(s1, 0x0d) ^ gfMultiply(s2, 0x09) ^ gfMultiply(s3, 0x0e);
  }
}

function encryptBlock(blockBytes, expandedKey, roundCount) {
  const state = copyBytes(blockBytes);

  addRoundKey(state, expandedKey, 0);

  for (let round = 1; round < roundCount; round += 1) {
    subBytes(state);
    shiftRows(state);
    mixColumns(state);
    addRoundKey(state, expandedKey, round);
  }

  subBytes(state);
  shiftRows(state);
  addRoundKey(state, expandedKey, roundCount);

  return state;
}

function decryptBlock(blockBytes, expandedKey, roundCount) {
  const state = copyBytes(blockBytes);

  addRoundKey(state, expandedKey, roundCount);

  for (let round = roundCount - 1; round > 0; round -= 1) {
    inverseShiftRows(state);
    inverseSubBytes(state);
    addRoundKey(state, expandedKey, round);
    inverseMixColumns(state);
  }

  inverseShiftRows(state);
  inverseSubBytes(state);
  addRoundKey(state, expandedKey, 0);

  return state;
}

export class AesEcbCipher {
  constructor(keyBytes) {
    const { expandedKey, roundCount } = expandKey(keyBytes);
    this.expandedKey = expandedKey;
    this.roundCount = roundCount;
  }

  encrypt(blockBytes) {
    const block = copyBytes(blockBytes);
    if (block.length !== BLOCK_SIZE) {
      throw new ValueError('plaintext block must be 16 bytes');
    }

    return encryptBlock(block, this.expandedKey, this.roundCount);
  }

  decrypt(blockBytes) {
    const block = copyBytes(blockBytes);
    if (block.length !== BLOCK_SIZE) {
      throw new ValueError('ciphertext block must be 16 bytes');
    }

    return decryptBlock(block, this.expandedKey, this.roundCount);
  }
}

