import { gfMultiply, xtime } from './finite_field.mjs';

function rotateLeft(value, shift) {
  return ((value << shift) | (value >>> (8 - shift))) & 0xff;
}

function multiplicativeInverse(value) {
  if (value === 0) {
    return 0;
  }

  for (let candidate = 1; candidate < 256; candidate += 1) {
    if (gfMultiply(value, candidate) === 1) {
      return candidate;
    }
  }

  throw new Error(`No multiplicative inverse for byte ${value}`);
}

function buildSBoxes() {
  const sBox = new Uint8Array(256);
  const inverseSBox = new Uint8Array(256);

  for (let value = 0; value < 256; value += 1) {
    const inverse = multiplicativeInverse(value);
    const substituted =
      inverse ^
      rotateLeft(inverse, 1) ^
      rotateLeft(inverse, 2) ^
      rotateLeft(inverse, 3) ^
      rotateLeft(inverse, 4) ^
      0x63;

    sBox[value] = substituted;
    inverseSBox[substituted] = value;
  }

  return { sBox, inverseSBox };
}

function buildRoundConstants() {
  const roundConstants = new Uint8Array(15);
  roundConstants[1] = 0x01;

  for (let index = 2; index < roundConstants.length; index += 1) {
    roundConstants[index] = xtime(roundConstants[index - 1]);
  }

  return roundConstants;
}

const sBoxes = buildSBoxes();

export const sBox = sBoxes.sBox;
export const inverseSBox = sBoxes.inverseSBox;
export const roundConstants = buildRoundConstants();

