export function xtime(value) {
  const byte = value & 0xff;
  const shifted = (byte << 1) & 0xff;
  return (byte & 0x80) === 0 ? shifted : shifted ^ 0x1b;
}

export function gfMultiply(left, right) {
  let multiplicand = left & 0xff;
  let multiplier = right & 0xff;
  let result = 0;

  while (multiplier !== 0) {
    if ((multiplier & 1) !== 0) {
      result ^= multiplicand;
    }

    multiplicand = xtime(multiplicand);
    multiplier >>>= 1;
  }

  return result;
}

